module Top;
    int i, j, k;
    initial begin
        i = 1;
        j = 0;
        k = (i == 0) -> (j++ > 0);
        $display("implication skipped %0d %0d", k, j);
        k = (i != 0) -> (j-- > 100);
        $display("implication evaluated %0d %0d", k, j);
        j = 1;
        k = i ? j++ : j--;
        $display("then %0d %0d", k, j);
    end
endmodule
